--[[
    Perishable Foods - core

    Two kinds of things never spoiled in vanilla:

    * Food items with no DaysFresh. The engine rots food that has it (and
      handles fridges and freezers itself), so PF_Scripts.lua gives the
      scripts their shelf lives. This file patches items that already exist.
    * Drinks (milk, juice, pop, wine, spirits): fluid containers, not food, so
      the engine never rots them. PF_Drinks.lua gives them a clock of their own.

    Rule for items the mod meets for the first time:
      * generated by the world (loot filled into containers): their age is the
        time since the apocalypse (days played plus the sandbox's months since
        the apocalypse), so unvisited places are already old. When the mod is
        added to an existing save the clock starts that day, so nothing is
        aged retroactively;
      * anything else (carried, dropped, opened in the loot window): fresh
        from the moment the mod sees it. A shelf does not rot all at once.
]]

PerishableFoods = PerishableFoods or {}
local PF = PerishableFoods

PF.DONE_KEY = "PF_done"
PF.NEVER = 1000000000 -- the vanilla "never rots" value

function PF.options()
    return SandboxVars.PerishableFoods or {}
end

function PF.enabled()
    return PF.options().Enabled ~= false
end

function PF.multiplier()
    return (PF.options().ShelfLifeMultiplier or 100) / 100
end

function PF.worldDays()
    return getGameTime():getWorldAgeHours() / 24
end

-- Days since the apocalypse: days played plus the "months since the
-- apocalypse" the sandbox started with (the same formula vanilla uses for
-- its power shut-off).
function PF.effectiveDay()
    return PF.worldDays() + (getSandboxOptions():getTimeSinceApo() - 1) * 30
end

-- Effective day from which things age. In a new game that is day 0, so a game
-- that starts months after the apocalypse already has aged food and drinks.
-- In a save that existed before the mod it is the day the mod first ran, so
-- nothing is aged retroactively. Stored in the save.
function PF.originDay()
    if PF._origin then return PF._origin end
    local data = ModData.getOrCreate("PerishableFoods")
    if data.origin == nil then
        -- a game starts with about 2 hours on the clock (7 AM to 9 AM); allow half a day
        local newGame = getGameTime():getWorldAgeHours() < 12
        data.origin = newGame and 0 or PF.effectiveDay()
    end
    PF._origin = data.origin
    return PF._origin
end

-- Days an item generated by the world has already aged.
function PF.worldGeneratedAge()
    return math.max(0, PF.effectiveDay() - PF.originDay())
end

----------------------------------------------------------------------------
-- Fridge and freezer (used for drinks; vanilla does this for food itself)
----------------------------------------------------------------------------

-- Vanilla FridgeFactor sandbox option (1..6) -> how fast things age in a fridge.
local FRIDGE_FACTORS = { 0.4, 0.3, 0.2, 0.1, 0.03, 0 }

function PF.fridgeFactor()
    return FRIDGE_FACTORS[SandboxVars.FridgeFactor or 3] or 0.2
end

-- The container an item finally sits in (bags are followed out).
function PF.outerContainer(container)
    if not container then return nil end
    for _ = 1, 5 do
        local bag = container:getContainingItem()
        if not bag then break end
        local outer = bag:getContainer()
        if not outer then return nil end
        container = outer
    end
    return container
end

-- Does a fridge or freezer have power? Same rule as vanilla: the grid has
-- electricity, or the world has not reached the power-shutoff day yet.
function PF.hasPower(outer)
    local square = outer:getSourceGrid()
    if not square then return true end
    if square:haveElectricity() then return true end
    local shut = SandboxVars.ElecShutModifier
    if shut and shut > -1 then
        local day = PF.effectiveDay()
        return day < shut
    end
    return false
end

-- Aging speed for something stored in `outer`: 1 normal, less in a fridge,
-- 0 in a freezer. Unpowered fridges and freezers do nothing.
function PF.rateFor(outer)
    if not outer then return 1 end
    local freezer, fridge = outer:isFreezer(), outer:isFridge()
    if not freezer and not fridge then return 1 end
    if not PF.hasPower(outer) then return 1 end
    if freezer then return 0 end
    return PF.fridgeFactor()
end

----------------------------------------------------------------------------
-- Food that already exists
----------------------------------------------------------------------------

-- Patch one food item once. `worldGenerated`: see the header.
function PF.patchItem(item, worldGenerated)
    if not item or not instanceof(item, "Food") then return false end
    local md = item:getModData()
    if md[PF.DONE_KEY] then return false end

    local script = getScriptManager():getItem(item:getFullType())
    local fresh = script and script:getDaysFresh() or PF.NEVER
    local rotten = script and script:getDaysTotallyRotten() or PF.NEVER
    if fresh >= PF.NEVER then
        -- Non-perishable for now. Not marked as done: an add-on or another mod may give
        -- this item a shelf life later, and then it has to be patched.
        return false
    end

    item:setOffAge(fresh)
    item:setOffAgeMax(rotten)
    item:setAge(worldGenerated and PF.worldGeneratedAge() or 0)
    md[PF.DONE_KEY] = true
    return true
end
